  const points = [{ rankShare: 0, equalPct: 0, actualTop1Mass: 0, label: "0" }];
  let mass = 0;
  sorted.forEach((l, i) => {
    mass += l.top1Pct;
    points.push({
      rankShare: Number((((i + 1) / n) * 100).toFixed(1)),
      equalPct: Number((((i + 1) / n) * 100).toFixed(1)),
      actualTop1Mass: Number(((mass / (n * 100)) * 100).toFixed(1)),
      label: l.short,
    });
  });
  return points;
})();

