// viz-types: vintage ?? dumbbells, Lorenz area+line, layer top-1/top-3 bars, HBM donut+prior slope, segment YoY bars, share??tightness scatter, regional bars + CoWoS composed | layout: default

type ViewId = "deltas" | "ladder" | "midstream" | "regions";
type LadderMetric = "top1Pct" | "top3CumPct" | "hhi";
type StageFilter = "all" | "upstream" | "midstream" | "downstream";
type SegmentMetric = "yoyPct" | "levelBn";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-xs font-semibold transition ${
              value === o.id ? "bg-slate-900 text-white" : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

function metricValue(layer: StackLayer, metric: LadderMetric): number {
  if (metric === "top1Pct") return layer.top1Pct;
  if (metric === "top3CumPct") return layer.top3CumPct;
  return layer.hhi;
}

