                  <YAxis
                    yAxisId="left"
                    domain={[100000, 150000]}
                    tick={{ fontSize: 10 }}
                    tickFormatter={(v) => `${Math.round(v / 1000)}k`}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    domain={[0, 90]}
                    tick={{ fontSize: 10 }}
                    unit="%"
                  />
                  <Tooltip />
                  <Bar
                    yAxisId="left"
                    dataKey="capacityWpm"
                    name="Capacity (wpm)"
                    fill="#0ea5e9"
                    opacity={0.85}
                    maxBarSize={44}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="nvidiaSharePct"
                    name="NVIDIA reserve %"
                    stroke="#f59e0b"
                    strokeWidth={2.5}
                    dot
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="tsmcSupplyPct"
                    name="TSMC supply %"
                    stroke="#8b5cf6"
                    strokeWidth={2}
                    dot
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="gapPct"
                    name="Supply gap %"
                    stroke="#ef4444"
                    strokeWidth={2}
                    strokeDasharray="4 4"
                    dot
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

